'use strict';

const {handleToken, hasAccessTokenHeader, hasApp2AppAuthorizationHeader, handleAuthorizationToken} = require('./access-token-handler');

function toHttpError(e) {
  const error = e.error ? e.error : e;
  const httpError = new Error(error.message);
  httpError.status = error.status;
  return httpError;
}

module.exports = async function (req, res, next) {
  if (hasAccessTokenHeader(req)) {
    try {
      await handleToken(req);
    } catch (e) {
      return next(toHttpError(e));
    }
    return next();
  }

  if (hasApp2AppAuthorizationHeader(req)) {
    try {
      await handleAuthorizationToken(req);
    } catch (e) {
      return next(toHttpError(e));
    }
  }

  return next();
};
